    "test": "vitest run",
    "theater": "node esbuild.config.mjs --theater",
    "typecheck": "tsc --noEmit && tsc --noEmit -p tsconfig.webview.json",
    "vscode:prepublish": "node esbuild.config.mjs --production"
  },
  "devDependencies": {
    "@eslint/js": "^9.0.0",
    "@types/node": "^24.0.0",
    "@types/vscode": "^1.75.0",
    "@vscode/vsce": "^3.9.2",
    "esbuild": "^0.25.0",
    "esbuild-svelte": "^0.9.5",
    "eslint": "^9.0.0",
    "jsdom": "^30.0.1",
    "svelte": "^5.56.9",
    "typescript": "^5.6.0",
    "typescript-eslint": "^8.0.0",
